INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '0ccf7fc3-bb1c-5b73-af83-8f3e32e18d14'::uuid, '4605ee44-0941-5f9b-9646-68eb9a96f230'::uuid, 'Résidence Abraj Alfadl', 'Résidence ABRAJ ALFADL - Appartements économiques à Mhamid 9 Située dans le quartier dynamique de Mhamid 9 à Marrakech, Résidence ABRAJ ALFADL vous propose un cadre de vie pratique, accessible et moderne. Ce projet immobilier allie qualité de construction, fonctionnalité et proximité des services essentiels. ### Une résidence pensée pour votre confort Ce programme résidentiel en R+3 se compose de : - Appartements économiques bien agencés - 2 à 3 chambres selon les configurations - Superficies de 51 m² à 76 m² - Magasins au rez-de-chaussée pour faciliter le quotidien ### Un emplacement stratégique Implantée dans l''un des secteurs les plus pratiques de Marrakech, la résidence vous permet de bénéficier de toutes les commodités à proximité : - Écoles pour vos enfants - Mosquées et lieux de culte - Hammams traditionnels - À 10 minutes de l''aéroport de Marrakech ### Avancement du projet - Première tranche: titres déjà disponibles - Deuxième tranche: livraison prévue en juillet 2025 Résidence ABRAJ ALFADL est l''opportunité idéale pour investir ou s''installer à Marrakech, avec un excellent rapport qualité/prix dans un quartier en pleine évolution.', 'Marrakech', 'M''Hamid 9', 'Ballouk 44, Commune Tassoultante, M''Hamid 9, 40000 Marrakech', '40000', 'MA', NULL, NULL, 'immobilier', 'residentiel', 'residentiel', 'livre', 'en_commercialisation', 100, NULL, NULL, 'https://media.chridari.ma/1026165f-4cf9-4342-9314-9c7e513a783c/images/01JV9WVTT