INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT 'd3e298fa-5196-5ff0-90f9-79518034b326'::uuid, 'cceb139b-c9f0-50c4-845a-96b0cf4663d3'::uuid, 'Majorelle Hills', 'Majorelle Hills est un projet signe Al Houda Groupe, situe sur BD Yaacoub El Mansour a Marrakech, dans le quartier Majorelle. Il propose des appartements, studios et duplex de 40 a 82 m2, avec 1 a 2 chambres et 1 a 2 salles de bain. Le projet se distingue par des finitions pensees pour le confort au quotidien: - construction en dalle post-tensionnee parasismique - isolation interieure et exterieure - marbre dans toute la maison - climatisation centralisee pre-installee - portes blindees - interphone video - garde-corps de balcon en verre - cuisine equipee avec plaque, hotte et four - salle de bain equipee avec separation de douche en verre Les residents profitent aussi de prestations pratiques: ascenseur, sous-sol, garage, parking, concierge, balcon et dressing. A proximite, vous retrouvez facilement ecole, maternelle, pharmacie, supermarche, centre commercial, cafe, boulangerie, banque, mosquee et jardin public pour un cadre de vie fluide et agreable.', 'Marrakech', 'Majorelle', 'BD Yaacoub El Mansour, Majorelle, 40000 Marrakech', '40000', 'MA', NULL, NULL, 'immobilier', 'residentiel', 'residentiel', 'en_construction', 'en_commercialisation', 55, '2027-01', NULL, 'https://media.chridari.ma/4263a3d0-106c-4ce6-ad40-3c31a152bc7b/images/01KXRBNWN6R33NJNQCBCQDXHW7-medium.jpg', $j$["https://media.chridari.ma/4263a3d0-106c-4ce6-ad40-3c31a152bc7b/images/01KXRBNWN6R33NJNQCBCQDXHW7-medium.jpg", "https://media.chridari.ma/76af4724-edb3-4a5f-a623-eca8