INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT 'd589545e-486a-53f0-ba11-1cdb7a0e1ad1'::uuid, 'cceb139b-c9f0-50c4-845a-96b0cf4663d3'::uuid, 'Residence Ranamir Semlalia', 'Residence Ranamir Semlalia est un projet signe Al Houda Groupe, situe a Semlalia a Marrakech, sur le boulevard 18 nv en face du restaurant Dar Yemma. Il propose des appartements, studios, duplex et locaux commerciaux avec des surfaces de 41 a 68 m2. Les logements offrent de 1 a 3 chambres et 1 a 2 salles de bain, avec des prestations pensees pour le confort au quotidien: - Climatisation centralisee pre-installee - Balcon avec garde-corps en verre - Cuisine equipee: plaque de cuisson, hotte et four - Cuisine en bois a 3 niveaux - Interphone video - Portes blindees - Ascenseur, concierge, sous-sol et parking - Piscine et issue de secours La construction en dalle post-tensionnee parasismique integre une isolation interieure et exterieure, tandis que les finitions mettent en avant le marbre, un salon avec bardage et une salle de bain equipee avec separation de douche en verre. A proximite, vous profitez de services pratiques comme cafe, banque et hammam pour un cadre de vie agreable a Semlalia.', 'Marrakech', 'Semlalia', 'boulevard 18 nv en face du retaurant dar yemma, Semlalia, 40000 Marrakech', '40000', 'MA', NULL, NULL, 'immobilier', 'mixte', 'mixte', 'en_construction', 'en_commercialisation', 55, '2027-04', NULL, 'https://media.chridari.ma/e71b4a90-3489-4e03-a49a-c51696958e06/images/01KY7N6DXD1T15HDMNJFQPXF7X-medium.jpg', $j$["https://media.chridari.ma/e71b4a90-3489-4e03-a49a-c51696958e06/images/01KY7N6DXD1T15HDMNJFQPXF7X-medium.