INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '1fba5b64-8243-5f37-baa8-ac1fa265334a'::uuid, 'cceb139b-c9f0-50c4-845a-96b0cf4663d3'::uuid, 'Al Houda Prestige', 'Al Houda Prestige est un projet signe Al Houda Groupe, situe a M''Hamid 9, Arrondissement Menara a Marrakech. Il propose une offre variee composee d''appartements, de duplex et de locaux commerciaux, avec des surfaces allant de 25 a 140 m2. Concu pour repondre aux besoins du quotidien, le projet met en avant des logements de 2 a 3 chambres avec 1 a 2 salles de bain, dans un cadre pratique et fonctionnel. Les atouts du projet: - Climatisation - Balcon - Concierge - Ascenseur - Cuisine equipee - Interphone video Les finitions de moyen standing apportent un confort apprecie, avec notamment une cuisine equipee comprenant placard 3 niveaux, plaque et hotte. La salle de bain equipee dispose de sanitaires encastres et d''une chasse d''eau suspendue. A Marrakech, Al Houda Prestige offre une belle opportunite pour habiter ou investir dans un projet alliant diversite des biens et equipements essentiels.', 'Marrakech', 'M''Hamid 9', 'M''Hamid 9, Arrondissement Ménara, Marrakech, M''Hamid 9, 40000 Marrakech', '40000', 'MA', NULL, NULL, 'immobilier', 'mixte', 'mixte', 'en_construction', 'en_commercialisation', 55, '2027-01', NULL, 'https://media.chridari.ma/d3bbab7c-2698-46d9-993a-247d879a6517/images/01KYHZ9KYNSXC1BEE4G5E3SFYX-medium.jpg', $j$["https://media.chridari.ma/d3bbab7c-2698-46d9-993a-247d879a6517/images/01KYHZ9KYNSXC1BEE4G5E3SFYX-medium.jpg", "https://media.chridari.ma/2714a93b-d634-4d5d-af1f-2d417f9944ea/images/01KYHZ9NA26CMG6ABCDV8AD17F-me